#include <bits/stdc++.h>
#define ll long long
using namespace std;
const ll INF = 1e12;
int n;
stack<char> st;
string c;
ll s;
int main(){
    cin >> n >> s >> c;
    for(int i = 0; i < n; i ++){
        if(c[i] == 'U'){
            if(s == 1) continue;
            if(st.size()){
                st.pop();
                continue;
            }
            s >>= 1;
        }else if(c[i] == 'L'){
            if((s << 1) > INF){
                st.push('L');
                continue;
            }
            s = s << 1;
        }else{
            if((s << 1 | 1) > INF){
                st.push('R');
                continue;
            }
            s = s << 1 | 1;
        }
    }
    cout << s << "\n";
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define ll long long
const int N = 1e5+10;
int n,m;
ll x;
vector<pair<int,int> > st;
int a[N],b[N];
int main(){
    cin>>n>>m>>x;
    for(int i=1;i<=n;i++){
        int p,c;
        cin>>p>>c;
        st.push_back(make_pair(p,c));
    }
    sort(st.begin(),st.end());
    for(int i=1;i<=m;i++){
        cin>>a[i]>>b[i];
    }
    vector<pair<int,int> > neg,pos;
    ll res=0;
    for(int i=1;i<=m;i++){
        if(a[i]>=b[i])
            pos.push_back(make_pair(a[i]-b[i],i));
        else{
            neg.push_back(make_pair(a[i]-b[i],i));
        }
        res+=1ll*b[i]*x;
    }
    sort(neg.begin(),neg.end());
    sort(pos.begin(),pos.end());
    reverse(pos.begin(),pos.end());
    int l=0,r=n-1;
    for(auto i:neg){
        while(r>=1&&st[r].second==0)r--;
        res+=1ll*(a[i.second]-b[i.second])*st[r].first;
        st[r].second-=1;
    }
    for(auto i:pos){
        while(l<=n&&st[l].second==0)l++;
        res+=1ll*(a[i.second]-b[i.second])*st[l].first;
        st[l].second-=1;
    }
    cout<<res*2<<"\n";
}
